package com.order.order_service.service;
import com.order.order_service.client.CatalogClient; import com.order.order_service.entity.CartItem; import com.order.order_service.repository.CartItemRepository; import jakarta.persistence.EntityNotFoundException; import java.math.BigDecimal; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@Service @Transactional(readOnly=true) public class CartService {private final CartItemRepository repo;private final CatalogClient catalog;public CartService(CartItemRepository r,CatalogClient c){repo=r;catalog=c;}
 public Map<String,Object> get(long uid){List<Map<String,Object>> rows=repo.findByUserIdOrderById(uid).stream().map(i->Map.<String,Object>of("id",i.getId(),"menuItemId",i.getMenuItemId(),"itemName",i.getItemName(),"menuItemName",i.getItemName(),"unitPrice",i.getUnitPrice(),"quantity",i.getQuantity(),"subtotal",i.subtotal(),"restaurantId",i.getRestaurantId())).toList();BigDecimal total=rows.stream().map(x->(BigDecimal)x.get("subtotal")).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("items",rows,"total",total);}
 @Transactional public Map<String,Object> add(long uid,long menu,int q,String token){Map<String,Object> item;try{item=catalog.getMenuItem(menu,"Bearer "+token);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Menu item is unavailable",e);}if(Boolean.FALSE.equals(item.get("available")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Menu item is not available");long restaurant=((Number)item.get("restaurantId")).longValue();var cart=repo.findByUserIdOrderById(uid);if(cart.stream().anyMatch(i->!i.getRestaurantId().equals(restaurant)))throw new ResponseStatusException(HttpStatus.CONFLICT,"A cart can contain items from one restaurant only");var old=repo.findByUserIdAndMenuItemId(uid,menu);if(old.isPresent()){if(old.get().getQuantity()+q>99)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Cart quantity cannot exceed 99");old.get().setQuantity(old.get().getQuantity()+q);}else repo.save(new CartItem(uid,menu,restaurant,Objects.toString(item.get("name")),new BigDecimal(item.get("price").toString()),q));return get(uid);}
 @Transactional public Map<String,Object> update(long uid,long id,int q){var i=repo.findByIdAndUserId(id,uid).orElseThrow(()->new EntityNotFoundException("Cart item not found"));i.setQuantity(q);return get(uid);}
 @Transactional public void remove(long uid,long id){repo.delete(repo.findByIdAndUserId(id,uid).orElseThrow(()->new EntityNotFoundException("Cart item not found")));} @Transactional public void clear(long uid){repo.deleteByUserId(uid);}
}
